package main

import (
	"fmt"
	"sync"
	"time"
	mapset "github.com/deckarep/golang-set/v2"
)

func main() {
	// Create a threadsafe set
	set := mapset.NewSet[int]()

	// Add some initial elements
	for i := 0; i < 10; i++ {
		set.Add(i)
	}

	// Start an iterator
	iter := set.Iterator()

	// Start a goroutine that tries to add elements while iterating
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 10; i < 20; i++ {
			time.Sleep(10 * time.Millisecond)
			set.Add(i)
			fmt.Printf("Added %d\n", i)
		}
	}()

	// Iterate through the elements
	count := 0
	for elem := range iter.C {
		fmt.Printf("Read %d\n", elem)
		count++
		time.Sleep(50 * time.Millisecond) // Slow down iteration to allow concurrent access
	}

	// Wait for the adding goroutine to finish
	wg.Wait()

	fmt.Printf("Total elements read: %d\n", count)
	fmt.Printf("Final set size: %d\n", set.Cardinality())
}
EOF
